private theorem norm_inv_real_smul (r : ℝ) (hr : 0 < r) (x : E) :
    ‖(r : 𝕜)⁻¹ • x‖ = ‖x‖ / r := by
  simp [norm_smul, abs_of_pos hr, div_eq_mul_inv, mul_comm]

private theorem norm_real_smul (r : ℝ) (hr : 0 ≤ r) (x : E) :
    ‖(r : 𝕜) • x‖ = r * ‖x‖ := by
  simp [norm_smul, abs_of_nonneg hr]

